param([switch]$SomenteVerificar, [string]$ArtesLocais)
$ErrorActionPreference = "Stop"
$payload = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("")) | ConvertFrom-Json
$assetUrl = "https://raw.githubusercontent.com/FlavioPlayGames/IPTVPremium/5db79a37e933d34ba72fdedfa0375185e0bb4f67/Artes-cores-unificadas-IPTV.zip"
$base = (Get-Location).Path
if (-not (Test-Path -LiteralPath (Join-Path $base "app/src/main"))) {
    if ((Test-Path -LiteralPath (Join-Path $base "src/main")) -and (Test-Path -LiteralPath (Join-Path $base "../settings.gradle.kts"))) { $base = Split-Path $base -Parent }
    else { throw "Abra o terminal na raiz do projeto Android." }
}
$base = [IO.Path]::GetFullPath($base)
$utf8 = New-Object Text.UTF8Encoding($false, $true)
function SafePath([string]$relative) {
    if ($relative -notmatch '^app/src/main/[A-Za-z0-9_./-]+$' -or $relative.Contains('..')) { throw "Caminho de arquivo invalido." }
    $path = [IO.Path]::GetFullPath((Join-Path $base $relative.Replace('/', [string][IO.Path]::DirectorySeparatorChar)))
    if (-not $path.StartsWith($base + [IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase)) { throw "Caminho fora do projeto." }
    return $path
}
function HashBytes([byte[]]$bytes) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-', '').ToLowerInvariant() }
    finally { $sha.Dispose() }
}
function Normalized([string]$text) {
    $text = $text.TrimStart([char]0xFEFF).Replace("`r`n", "`n")
    return ([regex]::Replace($text, '(?m)^// IPTV_[A-Z0-9_]+[ \t]*(?:\n|$)', '')).TrimEnd()
}
$writes = @{}
$relativeNames = @{}
$deletes = @()
foreach ($source in $payload.sources) {
    $path = SafePath $source.file
    $target = [string]$source.text
    if ((HashBytes ($utf8.GetBytes((Normalized $target)))) -ne $source.target) { throw "Payload de codigo inconsistente: $($source.file)" }
    $bom = $false
    $crlf = $true
    if (Test-Path -LiteralPath $path) {
        $original = [IO.File]::ReadAllBytes($path)
        $current = $utf8.GetString($original).TrimStart([char]0xFEFF)
        $hash = HashBytes ($utf8.GetBytes((Normalized $current)))
        if (@($source.accepted) -notcontains $hash) { throw "Versao diferente em $($source.file). Nada foi alterado. Envie o arquivo atual para adaptar a atualizacao." }
        if ($hash -eq $source.target) { continue }
        $bom = $original.Length -ge 3 -and $original[0] -eq 239 -and $original[1] -eq 187 -and $original[2] -eq 191
        $crlf = $current.Contains("`r`n")
        foreach ($marker in [regex]::Matches($current, '(?m)^// IPTV_[A-Z0-9_]+[ \t]*\r?$')) {
            $comment = $marker.Value.TrimEnd()
            if (-not $target.Contains($comment)) { $target += "`n" + $comment + "`n" }
        }
    } elseif (-not $source.create) { throw "Arquivo ausente: $($source.file). Nada foi alterado." }
    $target = $target.Replace("`r`n", "`n")
    if ($crlf) { $target = $target.Replace("`n", "`r`n") }
    $encoding = New-Object Text.UTF8Encoding([bool]$bom)
    $bytes = $encoding.GetPreamble() + $encoding.GetBytes($target)
    $writes[$path] = [byte[]]$bytes
    $relativeNames[$path] = $source.file
}
foreach ($item in $payload.deletions) {
    $path = SafePath $item.file
    if (Test-Path -LiteralPath $path) {
        if ((HashBytes ([IO.File]::ReadAllBytes($path))) -ne $item.sha256) { throw "Arte original modificada: $($item.file). Nada foi alterado." }
        $deletes += $path
        $relativeNames[$path] = $item.file
    }
}
$temp = Join-Path ([IO.Path]::GetTempPath()) ("IPTV-temas-" + [Guid]::NewGuid().ToString('N'))
[void][IO.Directory]::CreateDirectory($temp)
try {
    $zipPath = Join-Path $temp "artes.zip"
    if ($ArtesLocais) { [IO.File]::Copy((Get-Item -LiteralPath $ArtesLocais).FullName, $zipPath) }
    else {
        Write-Host "Baixando artes proprias dos temas…"
        Invoke-WebRequest -UseBasicParsing -Uri $assetUrl -OutFile $zipPath
    }
    if ((Get-FileHash -LiteralPath $zipPath -Algorithm SHA256).Hash.ToLowerInvariant() -ne $payload.assetZipSha) { throw "A verificacao SHA-256 das artes falhou. Nada foi alterado." }
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    $expected = @{}
    foreach ($asset in $payload.assets) { [void](SafePath $asset.file); $expected[$asset.file] = $asset }
    $archive = [IO.Compression.ZipFile]::OpenRead($zipPath)
    try {
        foreach ($entry in $archive.Entries) {
            if (-not $expected.ContainsKey($entry.FullName)) { throw "Arquivo inesperado ou duplicado no pacote de artes." }
            $asset = $expected[$entry.FullName]
            $expected.Remove($entry.FullName)
            if ($entry.Length -ne [long]$asset.size -or $entry.Length -gt 16777216) { throw "Tamanho de arte invalido." }
            $stream = $entry.Open()
            $memory = New-Object IO.MemoryStream
            try { $stream.CopyTo($memory); $bytes = $memory.ToArray() }
            finally { $stream.Dispose(); $memory.Dispose() }
            if ((HashBytes $bytes) -ne $asset.sha256) { throw "Arte inconsistente: $($asset.file)" }
            $path = SafePath $asset.file
            if (Test-Path -LiteralPath $path) {
                $currentHash = HashBytes ([IO.File]::ReadAllBytes($path))
                if ($currentHash -ne $asset.sha256) {
                    if (@($asset.accepted) -notcontains $currentHash) { throw "Arte existente modificada: $($asset.file). Nada foi alterado." }
                    $writes[$path] = [byte[]]$bytes
                    $relativeNames[$path] = $asset.file
                }
            } else { $writes[$path] = [byte[]]$bytes; $relativeNames[$path] = $asset.file }
        }
    } finally { $archive.Dispose() }
    if ($expected.Count -ne 0) { throw "O pacote de artes esta incompleto. Nada foi alterado." }
    if ($SomenteVerificar) { Write-Host "Verificacao concluida: codigo e artes compativeis. Nenhum arquivo do projeto foi alterado." -ForegroundColor Green; return }
    if ($writes.Count -eq 0 -and $deletes.Count -eq 0) { Write-Host "O teclado numerico e o botao Continuar padronizado ja estao aplicados." -ForegroundColor Green; return }
    $backup = Join-Path $base (".iptv-backups/teclado-pin-" + (Get-Date -Format "yyyyMMdd-HHmmssfff"))
    foreach ($path in @($writes.Keys) + @($deletes)) {
        if (Test-Path -LiteralPath $path) {
            $copy = Join-Path $backup ($relativeNames[$path].Replace('/', [string][IO.Path]::DirectorySeparatorChar))
            [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($copy))
            Copy-Item -LiteralPath $path -Destination $copy
        }
    }
    foreach ($path in $writes.Keys) {
        [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($path))
        $pending = $path + ".iptv-tmp"
        try { [IO.File]::WriteAllBytes($pending, $writes[$path]); Move-Item -LiteralPath $pending -Destination $path -Force }
        finally { if (Test-Path -LiteralPath $pending) { Remove-Item -LiteralPath $pending } }
    }
    foreach ($path in $deletes) { Remove-Item -LiteralPath $path }
    Write-Host "Concluido: teclado numerico proprio para PIN e botao Continuar padronizado." -ForegroundColor Green
    Write-Host "Escolha em Configuracoes > Aparencia. O dourado continua como padrao."
    Write-Host "Fundos exclusivos preservados. Arquivos anteriores: $backup"
    Write-Host "Agora execute Gerar-APKs.ps1 e instale sobre o aplicativo atual, sem desinstalar."
} finally { if (Test-Path -LiteralPath $temp) { Remove-Item -LiteralPath $temp -Recurse -Force } }
